const storage={read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Browser storage is unavailable; changes will last for this session.');return false}}};
let saved=new Set(storage.read('wetland-saved-v1',[]).filter(x=>typeof x==='string'));
let custom=storage.read('wetland-custom-v1',[]).filter(t=>t&&typeof t.id==='string'&&t.id.startsWith('custom-')&&typeof t.name==='string'&&typeof t.endpoint==='string'&&/^https:\/\//.test(t.endpoint)).map(t=>({...t,custom:true,tools:[],benefits:['Review this server’s documentation and data permissions before connecting.'],scope:'User-submitted entry stored in this browser. Endpoint and capabilities have not been verified.'}));
let state={nav:'all',category:'All tools',query:'',sort:'featured',list:false,expanded:null,tab:'overview'};
const $=selector=>document.querySelector(selector);
const allTools=()=>[...defaults,...custom];
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function renderFilters(){const categories=['All tools','Knowledge & brand','Programmes','Fundraising','Operations','Finance'];$('.filters').innerHTML=categories.map(c=>`<button class="filter ${state.category===c?'active':''}" data-category="${escapeHtml(c)}" aria-pressed="${state.category===c}">${escapeHtml(c)}<span>${allTools().filter(t=>c==='All tools'||t.category===c).length}</span></button>`).join('')}
function filteredTools(){let tools=allTools().filter(t=>(state.nav!=='saved'||saved.has(t.id))&&(state.nav!=='custom'||t.custom)&&(state.category==='All tools'||t.category===state.category));const q=state.query.trim().toLowerCase();if(q)tools=tools.filter(t=>[t.name,t.description,t.owner,t.category,...t.tools.flat()].join(' ').toLowerCase().includes(q));if(state.sort==='az')tools.sort((a,b)=>a.name.localeCompare(b.name));if(state.sort==='status')tools.sort((a,b)=>Number(!!b.endpoint)-Number(!!a.endpoint));return tools}
function render(){renderFilters();const tools=filteredTools();$('#nav-total').textContent=allTools().length;$('#total-stat').textContent=allTools().length;$('#saved-count').textContent=allTools().filter(t=>saved.has(t.id)).length;$('#results').textContent=`Showing ${tools.length} ${tools.length===1?'tool':'tools'}${state.query?` for “${state.query}”`:''}`;$('#cards').classList.toggle('list',state.list);$('#cards').innerHTML=tools.map(cardMarkup).join('');$('#empty').classList.toggle('hidden',tools.length>0);$('#empty-description').textContent=state.nav==='saved'?'Save a tool using its bookmark button, then find it here.':state.nav==='custom'?'Use “Showcase an MCP” to add your first entry.':'Try another search term or reset your category filters.';$('#reset').textContent=state.nav==='saved'?'Explore all tools':state.nav==='custom'?'Showcase an MCP':'Reset filters';}
function cardMarkup(t){const open=state.expanded===t.id;return `<article class="tool-card ${open?'expanded':''}" id="card-${escapeHtml(t.id)}"><div class="card-content"><div class="card-top"><span class="tool-icon ${escapeHtml(t.tone||'blue')}">${icon(t.icon)}</span><button class="icon-button bookmark ${saved.has(t.id)?'saved':''}" data-save="${escapeHtml(t.id)}" aria-label="${saved.has(t.id)?'Unsave':'Save'} ${escapeHtml(t.name)}" aria-pressed="${saved.has(t.id)}">${icon('bookmark')}</button></div><h3>${escapeHtml(t.name)}</h3><p class="description">${escapeHtml(t.description)}</p><div class="tool-tags"><span class="tag">${escapeHtml(t.category)}</span><span class="tag ${t.id==='brand'?'live':''}">${escapeHtml(t.status)}</span></div></div><div class="card-footer"><span class="owner">${icon('users')}${escapeHtml(t.owner)}</span><button class="expand" data-expand="${escapeHtml(t.id)}" aria-expanded="${open}" aria-controls="detail-${escapeHtml(t.id)}">Explore MCP${icon('arrow')}</button></div>${open?detailMarkup(t):`<div id="detail-${escapeHtml(t.id)}" hidden></div>`}</article>`}
function detailMarkup(t){return `<section class="detail" id="detail-${escapeHtml(t.id)}" aria-label="${escapeHtml(t.name)} details"><div class="detail-tabs" role="tablist" aria-label="Tool details">${[['overview','Overview'],['tools',`Tools & capabilities${t.tools.length?' · '+t.tools.length:''}`],['connect','Connection']].map(([id,label])=>`<button class="detail-tab ${state.tab===id?'active':''}" id="tab-${id}" data-tab="${id}" role="tab" aria-selected="${state.tab===id}" aria-controls="panel-${id}" tabindex="${state.tab===id?'0':'-1'}">${label}</button>`).join('')}</div><div role="tabpanel" id="panel-${state.tab}" aria-labelledby="tab-${state.tab}">${state.tab==='overview'?overviewMarkup(t):state.tab==='tools'?toolsMarkup(t):connectionMarkup(t)}</div><div class="detail-bottom"><p>${t.custom?'Submitted in this browser · Unverified':t.id==='brand'?'Source: brand MCP · Inspected 17 October 2026':'Proposed example · Fictional Water Care Canada workspace'}</p><button class="close-card" data-collapse="${escapeHtml(t.id)}">Collapse details${icon('chevron')}</button></div></section>`}
function overviewMarkup(t){return `<div class="detail-layout"><div><h4>What this helps you do</h4><p>${escapeHtml(t.purpose||t.description)}</p><ul>${t.benefits.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul><p class="scope">${escapeHtml(t.scope)}</p></div><div><h4>Ownership & readiness</h4><dl>${[['Sponsor',t.sponsor],['Maintainer',t.maintainer],['Release',t.version],['Next review',t.review],['Data & access',t.access],['Output state',t.id==='brand'?'Reference guidance':'Draft · human review required']].map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHtml(v)}</dd></div>`).join('')}</dl></div></div>`}
function toolsMarkup(t){return `<h4>${t.id==='brand'?'Tools exposed by this MCP':t.custom?'Capabilities not verified':'Proposed capabilities'}</h4><p>${t.id==='brand'?'Read-only tools confirmed through MCP tools/list.':t.custom?'This server has not been inspected. Review its documentation before granting access.':'These tool names describe a possible implementation. They are not callable endpoints.'}</p>${t.tools.map(([name,desc])=>`<div class="tool-row"><code>${escapeHtml(name)}</code><p>${escapeHtml(desc)}</p></div>`).join('')}`}
function configFor(t){return JSON.stringify({mcpServers:{[t.id==='brand'?'wateraid-brand-hub':t.id]:{url:t.endpoint,transport:'streamable-http'}}},null,2)}
function connectionMarkup(t){if(!t.endpoint)return `<div class="detail-layout"><div><h4>This connection is still a concept.</h4><p>There is no live endpoint for this tool. It needs an implementation, a named maintainer, agreed data access and a reviewed pilot before anyone can connect.</p><p class="scope">Use the live Brand & design system MCP to try a working connection today.</p></div><div><h4>Before a pilot</h4><ul><li>Confirm the business owner and maintainer.</li><li>Agree the data boundary and necessary approvals.</li><li>Build and evaluate with synthetic data.</li><li>Define human review and release requirements.</li></ul></div></div>`;return `<div class="detail-layout"><div><h4>${t.custom?'Submitted endpoint':'Connect your agent'}</h4><p class="connection-note">${t.custom?'This endpoint is user submitted and has not been verified.':'Streamable HTTP · no authentication · read-only. Add this server to an MCP-compatible client. Client configuration formats may vary.'}</p><code class="endpoint">${escapeHtml(t.endpoint)}</code><div class="connection-actions"><button class="button primary" data-copy="config" data-tool="${escapeHtml(t.id)}">${icon('copy')}Copy configuration</button><button class="button secondary" data-copy="url" data-tool="${escapeHtml(t.id)}">Copy URL</button>${t.id==='brand'?`<a class="button secondary" href="${BRAND_URL}#agents" target="_blank" rel="noreferrer">Connection guide${icon('external')}</a>`:''}</div><p class="scope">${escapeHtml(t.scope)}</p></div><div><h4>Example client configuration</h4><pre class="config">${escapeHtml(configFor(t))}</pre></div></div>`}
function setNav(nav){state.nav=nav;state.expanded=null;state.category='All tools';state.query='';$('#search').value='';const titles={all:['MCP marketplace','Good tools. Connected to a greater purpose.'],saved:['Saved tools','Your collection of useful connections.'],custom:['My submissions','The tools you’re bringing to the collection.'],overview:['Workspace overview','A little context. A lot of possibility.']};const [title,description]=titles[nav];$('#page-title').innerHTML=escapeHtml(title)+'<span>.</span>';$('#page-description').textContent=description;$('#breadcrumb').textContent=title;$('#welcome').classList.toggle('hidden',nav==='saved'||nav==='custom');$('#summary').classList.toggle('hidden',nav==='saved'||nav==='custom');document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===nav);if(b.dataset.nav===nav)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});closeNavigation();render();}
function openSubmission(){$('#submission').classList.remove('hidden');$('#submission').scrollIntoView({block:'start'});$('#tool-form input').focus()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){setNav(b.dataset.nav);return}if(b.dataset.category){state.category=b.dataset.category;render();return}if(b.dataset.save){const id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);storage.write('wetland-saved-v1',[...saved]);render();toast(saved.has(id)?'Tool added to your saved collection.':'Tool removed from saved collection.');const target=$(`[data-save="${id}"]`);target?.focus({preventScroll:true});return}if(b.dataset.expand){state.expanded=b.dataset.expand;state.tab='overview';render();const card=$(`#card-${state.expanded}`);card.scrollIntoView({block:'nearest'});card.querySelector('[role="tab"]').focus({preventScroll:true});return}if(b.dataset.collapse){const id=b.dataset.collapse;state.expanded=null;render();$(`[data-expand="${id}"]`)?.focus({preventScroll:true});return}if(b.dataset.tab){state.tab=b.dataset.tab;render();$(`#tab-${state.tab}`).focus({preventScroll:true});return}if(b.dataset.copy){const t=allTools().find(x=>x.id===b.dataset.tool);const value=b.dataset.copy==='url'?t.endpoint:configFor(t);try{await navigator.clipboard.writeText(value);toast(b.dataset.copy==='url'?'MCP endpoint copied.':'MCP configuration copied.')}catch{toast('Clipboard unavailable. Select and copy the configuration shown.')}return}});
$('#search').addEventListener('input',e=>{state.query=e.target.value;render()});$('#sort').addEventListener('change',e=>{state.sort=e.target.value;render()});$('#grid-view').onclick=()=>setView(false);$('#list-view').onclick=()=>setView(true);function setView(list){state.list=list;$('#grid-view').classList.toggle('selected',!list);$('#grid-view').setAttribute('aria-pressed',String(!list));$('#list-view').classList.toggle('selected',list);$('#list-view').setAttribute('aria-pressed',String(list));render()}
$('#add-tool').onclick=openSubmission;$('#add-tool-bottom').onclick=openSubmission;$('#close-submission').onclick=()=>{$('#submission').classList.add('hidden');$('#add-tool').focus()};$('#explore').onclick=()=>{$('#catalogue').scrollIntoView({block:'start'});$('#search').focus({preventScroll:true})};$('#reset').onclick=()=>{if(state.nav==='custom'){openSubmission();return}setNav('all')};$('#how-it-works').onclick=()=>{$('#explainer').classList.remove('hidden');$('#explainer').scrollIntoView({block:'start'});$('#close-explainer').focus({preventScroll:true});closeNavigation();$('#close-explainer').focus({preventScroll:true})};$('#close-explainer').onclick=()=>{$('#explainer').classList.add('hidden');$('#how-it-works').focus()};function closeNavigation(){const wasOpen=$('#sidebar').classList.contains('open');$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','Open navigation');if(wasOpen)$('#menu').focus({preventScroll:true})} $('#menu').onclick=()=>{if($('#sidebar').classList.contains('open')){closeNavigation();return}$('#sidebar').classList.add('open');$('#menu').setAttribute('aria-expanded','true');$('#menu').setAttribute('aria-label','Close navigation');$('[data-nav="overview"]').focus({preventScroll:true})};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();$('#search').focus()}if(e.key==='Escape'){if($('#sidebar').classList.contains('open')){closeNavigation();return}closeNavigation();if(state.expanded){const id=state.expanded;state.expanded=null;render();$(`[data-expand="${id}"]`)?.focus()}}if(e.target.matches('[role="tab"]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=['overview','tools','connect'];let i=tabs.indexOf(state.tab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;state.tab=tabs[i];render();$(`#tab-${state.tab}`).focus({preventScroll:true})}});
$('#tool-form').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);let endpoint;try{endpoint=new URL(form.get('endpoint'));if(endpoint.protocol!=='https:')throw Error();if(endpoint.username||endpoint.password)throw Error()}catch{$('#form-error').textContent='Enter an HTTPS endpoint without embedded credentials.';return}if(allTools().some(t=>t.endpoint===endpoint.href)){$('#form-error').textContent='That endpoint is already in the catalogue.';return}const name=String(form.get('name')).trim();const owner=String(form.get('owner')).trim();const description=String(form.get('description')).trim();if(!name||!owner||!description){$('#form-error').textContent='Complete the name, maintainer and description.';return}const item={id:'custom-'+Date.now().toString(36),name,description,category:String(form.get('category')),owner,endpoint:endpoint.href,icon:'plug',tone:'blue',status:'Unverified',version:'User submission',sponsor:owner,maintainer:owner,review:'Not scheduled',access:'Unverified · review before connecting',purpose:description,scope:'User-submitted entry stored in this browser. Endpoint and capabilities have not been verified.',tools:[],benefits:['Review this server’s documentation and data permissions before connecting.'],custom:true};custom.push(item);storage.write('wetland-custom-v1',custom);e.target.reset();$('#form-error').textContent='';$('#submission').classList.add('hidden');setNav('custom');state.expanded=item.id;render();toast('MCP added to your browser’s catalogue.');$('#catalogue').scrollIntoView({block:'start'})});
$('#export').onclick=()=>{const exported={title:'Wetland MCP catalogue',exportedAt:new Date().toISOString(),scope:'Research prototype; fictional Water Care tool concepts. Entries do not grant access.',tools:filteredTools().map(t=>({...t,saved:saved.has(t.id)}))};const url=URL.createObjectURL(new Blob([JSON.stringify(exported,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='wetland-mcp-catalogue.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Catalogue exported as JSON.')};
render();
